                i += 1
                continue
            color = values[i]
            j = i + 1
            while j < len(values) and values[j] == color:
                j += 1
            result.append((color, i, j - 1))
            i = j
        return result

    candidates = []

    # Bars on top and bottom: segment indices are columns.
    for a in segments(grid[0]):
        for b in segments(grid[-1]):
            if a[0] == b[0]:
                candidates.append((a[2] - a[1] + b[2] - b[1],
                                   "horizontal", a, b))

    # Bars on left and right: segment indices are rows.
    left = segments([grid[r][0] for r in range(h)])
    right = segments([grid[r][-1] for r in range(h)])
    for a in left:
        for b in right:
            if a[0] == b[0]:
                candidates.append((a[2] - a[1] + b[2] - b[1],
                                   "vertical", a, b))

    if not candidates:
        return [row[:] for row in grid]

    _, orientation, seg_a, seg_b = max(candidates, key=lambda x: x[0])
    wall_color = seg_a[0]
    out = [row[:] for row in grid]

    markers = [
        (r, c, grid[r][c])
        for r in range(h) for c in range(w)
        if grid[r][c] != bg and grid[r][c] != wall_color
    ]

